import{I as a,b as r,c as i,O as t}from"./chunks/framework.BGwiwaG1-ghp20261122.js";const f=JSON.parse('{"title":"少女回战 Wiki 资料站导航｜武将图鉴、阵容与养成攻略","titleTemplate":false,"description":"查少女回战日服和繁中服的武将首发日期、技能与立绘，以及日服星灵获取、星海套养成、PVE 和 PVP 阵容。","frontmatter":{"title":"少女回战 Wiki 资料站导航｜武将图鉴、阵容与养成攻略","titleTemplate":false,"description":"查少女回战日服和繁中服的武将首发日期、技能与立绘，以及日服星灵获取、星海套养成、PVE 和 PVP 阵容。","breadcrumbLabel":"资料站导航","lastmod":"2026-11-24"},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md"}'),s={name:"guides/index.md"};function l(n,e,o,h,d,u){return r(),i("div",null,[...e[0]||(e[0]=[t('<article class="page-shell knowledge-page reference-guide"><h1 id="少女回战资料站导航" tabindex="-1">少女回战资料站导航 <a class="header-anchor" href="#少女回战资料站导航" aria-label="Permalink to &quot;少女回战资料站导航&quot;">​</a></h1><p>少女回战 Wiki（kaisendb.com）收录日服《少女廻戦》和繁中服《少女迴戰》的武将技能、分服首发日期与高清立绘。日服的材料获取和限时活动可按资源名和活动名查询。</p><h2 id="新手攻略与选服" tabindex="-1">新手攻略与选服 <a class="header-anchor" href="#新手攻略与选服" aria-label="Permalink to &quot;新手攻略与选服&quot;">​</a></h2><ul><li><a href="/download/">iOS 与安卓下载</a>可找到日服和繁中服的官方商店，<a href="/servers/">新区开服查询</a>列出各区服的公告入口。</li><li><a href="/beginner/#beginner-route">新手游玩必看</a>给出开局、推图和资源安排。<a href="/beginner/#beginner-tasks">五日任务</a>与<a href="/beginner/#beginner-level-unlocks">等级解锁</a>可核对阶段奖励和各玩法的开放门槛。</li></ul><h2 id="武将图鉴、立绘与皮肤" tabindex="-1">武将图鉴、立绘与皮肤 <a class="header-anchor" href="#武将图鉴、立绘与皮肤" aria-label="Permalink to &quot;武将图鉴、立绘与皮肤&quot;">​</a></h2><ul><li><a href="/heroes/">武将图鉴</a>可按名称和稀有度查技能、招募、宝物及两服首发日期。<a href="/weapons/">武灵躯</a>与<a href="/transcendents/">超凡者</a>有各自的技能资料。</li><li><a href="/art-library/">立绘图鉴</a>可按角色名查看和下载原版立绘，进入<a href="/skins/">皮肤图鉴</a>可单独查变装与获取方式。</li></ul><h2 id="_11-月-20-日更新" tabindex="-1">11 月 20 日更新 <a class="header-anchor" href="#_11-月-20-日更新" aria-label="Permalink to &quot;11 月 20 日更新&quot;">​</a></h2><p>现在·幽灵再现（UR+）于 11 月 19 日在日服登场，11 月 20 日在繁中服登场。限时活动在日服叫「暗夜之影」，在繁中服叫「午夜魅影」。可查两服弹珠排期、武将碎片和三件新宝物的获取方式。<a href="/heroes/603680">武将详情</a> · <a href="/art-library/?asset=hero-603680">原版立绘</a> · <a href="/events/dark-shadow/">本期活动攻略</a></p><h2 id="日服与繁中服首发日期" tabindex="-1">日服与繁中服首发日期 <a class="header-anchor" href="#日服与繁中服首发日期" aria-label="Permalink to &quot;日服与繁中服首发日期&quot;">​</a></h2><p><a href="/heroes/601174#character-history">文豪之梦·小元（UR+）</a>在日服于 2026 年 11 月 12 日首次开放招募，繁中服于 2026 年 11 月 13 日首次开放招募。两服参考的招募记录与客户端资料列在武将页的「首次开放时间」。</p><p><a href="/releases/">首次开放时间表</a>可以按区服核对武将、武灵躯和超凡者的登场日期。同一角色的稀有度和形态各有记录，例如<a href="/heroes/601170">小元（R）</a>和文豪之梦·小元（UR+）。</p><h2 id="data-sources" tabindex="-1">资料来源与核对方式 <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;资料来源与核对方式 {#data-sources}&quot;">​</a></h2><p>武将按形态和区服分别建档。比较两服进度时，可以先看<a href="/releases/#release-comparison">已有出处的首发日期对照</a>，再点日期查看对应资料。同一形态可能在两服同日登场，也可能相隔数日。</p><ul><li><strong>客户端记录</strong>。以<a href="/heroes/603680#character-history">现在·幽灵再现的分服记录</a>为例，首发日期取自对应区服的招募记录。<a href="https://shupdate.menaapp.net/updatePackage/android/0.821/0_821_6/versions.csv" target="_blank" rel="noreferrer">日服 0.821.6 版本清单</a>和<a href="https://shtwnupdate.menaapp.net/updatePackage/android/0.840/0_840_61/versions.csv" target="_blank" rel="noreferrer">繁中服 0.840.61 版本清单</a>标明核对时使用的客户端版本。</li><li><strong>公告与历史记录</strong>。角色页标明资料属于官方发布、公告整理或社区记录。遇到「最早记录」，该日期表示资料能够证实角色当时已经登场，首发日期另列核实状态。</li><li><strong>道具取得条件</strong>。查看物品页的常驻来源、单次消耗和限购周期。例如<a href="/resources/311/#permanent-sources">星灵</a>在日服金锭商店和盟约商店分别受主角等级和同盟等级限制。</li></ul><h2 id="阵容推荐与武将强度榜" tabindex="-1">阵容推荐与武将强度榜 <a class="header-anchor" href="#阵容推荐与武将强度榜" aria-label="Permalink to &quot;阵容推荐与武将强度榜&quot;">​</a></h2><ul><li><a href="/teams/">阵容推荐</a>提供 PVE 首排和 PVP 编成的站位与搭配思路。<a href="/teams/loadouts/">武将强度榜</a>可查 SS、S 档武将的入榜理由与使用条件。</li></ul><h2 id="装备养成、资源获取与宝物羁绊" tabindex="-1">装备养成、资源获取与宝物羁绊 <a class="header-anchor" href="#装备养成、资源获取与宝物羁绊" aria-label="Permalink to &quot;装备养成、资源获取与宝物羁绊&quot;">​</a></h2><ul><li>装备资源充足时优先做星海套，星海材料不足时用湮灭脉冲过渡。<a href="/equipment/#progression">装备提升路径</a>可查合成与升阶材料，<a href="/power/">提升战力</a>可查各养成阶段的资源分配。</li><li>日服主角达到 80 级，可在金锭商店用 200 金锭购买 1 个星灵，每日限购 100 次。加入 1 级或以上同盟后，可在盟约商店用 600 盟约币兑换 1 个星灵，每周限购 20 次。可查<a href="/resources/311/#permanent-sources">星灵常驻来源</a>、<a href="/resources/">资源获取</a>和<a href="/events/#current">本期活动</a>。</li><li><a href="/dragon-soul/builds/">武将龙魂技能搭配</a>可查每个已开放武将形态的随机与固定天赋、替换建议和 45 级额外槽解锁条件。</li><li><a href="/bonds/treasures/">宝物羁绊</a>查激活条件和星级奖励。<a href="/marriage/">婚嫁与誓约</a>查婚戒、婚纱和梦中春日的开启条件。</li></ul><section lang="ja"><h2 id="jp-guide">少女廻戦攻略Wiki</h2><p>日本版『少女廻戦』の攻略案内です。武将の性能やガチャの初登場日、編成、装備素材の入手先を掲載しています。各記事は中国語（簡体字・繁体字）で読めます。</p><ul><li><a href="/beginner/">初心者ガイド</a>で序盤の進め方や機能の解放条件を確認できます。</li><li><a href="/heroes/">武将図鑑</a>と<a href="/teams/">編成例</a>で武将のスキルや配置を調べられます。</li><li><a href="/events/#current">開催中のイベント</a>で日本版の開催期間や報酬を確認できます。</li></ul></section><p>想交流阵容、活动和区服进度，可打开<a href="/community/">玩家社区</a>。</p></article>',1)])])}const p=a(s,[["render",l]]);export{f as __pageData,p as default};
